#!/usr/bin/env python3
"""Generate vaxcrate_analysis.json and vaxcrate_summary.md per task contract."""

import csv
import json
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from typing import Any, Dict, List, Optional, Tuple


Q2 = Decimal('0.01')


def dnum(x: Any) -> Optional[Decimal]:
    """Parse a number-like value to Decimal; return None for blanks/invalids."""
    if x is None:
        return None
    if isinstance(x, Decimal):
        return x
    if isinstance(x, (int, float)):
        # Use str() to avoid binary float artifacts as much as possible.
        try:
            return Decimal(str(x))
        except InvalidOperation:
            return None
    if isinstance(x, str):
        s = x.strip()
        if s == "":
            return None
        try:
            return Decimal(s)
        except InvalidOperation:
            return None
    return None


def round2(x: Decimal) -> Decimal:
    return x.quantize(Q2, rounding=ROUND_HALF_UP)


def s_norm(x: Any) -> str:
    return ("" if x is None else str(x)).strip()


def load_csv_rows(path: str) -> List[Dict[str, str]]:
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        # Normalize header keys by stripping whitespace.
        fieldnames = [fn.strip() if fn is not None else "" for fn in (reader.fieldnames or [])]
        rows: List[Dict[str, str]] = []
        for raw in reader:
            row: Dict[str, str] = {}
            for k, v in raw.items():
                kk = (k.strip() if k is not None else "")
                row[kk] = "" if v is None else str(v)
            rows.append(row)
        return rows


def maybe_parse_alias_labels(v: Any) -> List[str]:
    """alias_labels may be a list, a JSON list string, or a comma-separated string."""
    if v is None:
        return []
    if isinstance(v, list):
        return [s_norm(x) for x in v if s_norm(x)]
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return []
        # If it looks like JSON, try JSON parsing.
        if (s.startswith('[') and s.endswith(']')) or (s.startswith('"') and s.endswith('"')):
            try:
                parsed = json.loads(s)
                if isinstance(parsed, list):
                    return [s_norm(x) for x in parsed if s_norm(x)]
            except Exception:
                pass
        # Fallback: split by comma.
        parts = [p.strip() for p in s.split(',')]
        return [p for p in parts if p]
    # Unknown type: stringify.
    s = s_norm(v)
    return [s] if s else []


def extract_campaigns(obj: Any) -> List[Dict[str, Any]]:
    """Walk an arbitrary JSON structure and collect dicts that look like campaigns."""
    found: List[Dict[str, Any]] = []

    def walk(x: Any) -> None:
        if isinstance(x, dict):
            if 'campaign_id' in x and 'campaign_name' in x:
                found.append(x)
                return
            for vv in x.values():
                walk(vv)
        elif isinstance(x, list):
            for it in x:
                walk(it)

    walk(obj)

    # De-duplicate by campaign_id (keep first occurrence).
    seen = set()
    uniq: List[Dict[str, Any]] = []
    for c in found:
        cid = s_norm(c.get('campaign_id'))
        if not cid or cid in seen:
            continue
        seen.add(cid)
        uniq.append(c)
    return uniq


def latest_billing_payment(
    billing_rows: List[Dict[str, str]],
    labels: List[str],
) -> Tuple[Optional[Decimal], Optional[Dict[str, str]]]:
    """Return (payment, chosen_row) or (None, None) if no active row found."""
    label_set = {s_norm(l) for l in labels if s_norm(l)}
    candidates = []
    for r in billing_rows:
        campaign_label = s_norm(r.get('campaign_label'))
        status = s_norm(r.get('status')).lower()
        if status != 'active':
            continue
        if campaign_label not in label_set:
            continue
        candidates.append(r)

    if not candidates:
        return None, None

    # Lexicographically largest cycle_tag.
    candidates.sort(key=lambda rr: s_norm(rr.get('cycle_tag')))
    chosen = candidates[-1]
    pay = dnum(chosen.get('payment_per_dispatch_per_clinic_usd'))
    return pay, chosen


def resolve_active_clinics(
    overrides_rows: List[Dict[str, str]],
    campaign_id: str,
    default_active_clinics: Any,
) -> Tuple[Decimal, Optional[Dict[str, str]]]:
    valid = []
    for r in overrides_rows:
        if s_norm(r.get('campaign_id')) != campaign_id:
            continue
        state = s_norm(r.get('state')).lower()
        if state != 'approved':
            continue
        rev_s = s_norm(r.get('revision'))
        ac_s = s_norm(r.get('active_clinics'))
        if rev_s == "" or ac_s == "":
            continue
        rev = dnum(rev_s)
        ac = dnum(ac_s)
        if rev is None or ac is None:
            continue
        valid.append((rev, ac, r))

    if valid:
        valid.sort(key=lambda t: t[0])
        rev, ac, row = valid[-1]
        return ac, row

    # Fallback.
    dflt = dnum(default_active_clinics)
    if dflt is None:
        dflt = Decimal('0')
    return dflt, None


def main() -> None:
    # A. Load data
    with open('/root/campaign_manifest.json') as f:
        manifest = json.load(f)
    campaigns_raw = extract_campaigns(manifest)

    crate_rows = load_csv_rows('/root/crate_cost.csv')
    billing_rows = load_csv_rows('/root/billing.csv')
    overrides_rows = load_csv_rows('/root/location_overrides.csv')
    susp_rows = load_csv_rows('/root/suspensions.csv')

    # Build suspension set
    held_campaign_ids = {
        s_norm(r.get('campaign_id'))
        for r in susp_rows
        if s_norm(r.get('suspension_status')).lower() == 'hold'
    }

    # Build crate cost map
    crate_cost_by_tier: Dict[str, Decimal] = {}
    for r in crate_rows:
        tier = s_norm(r.get('crate_tier'))
        cost = dnum(r.get('crate_cost_usd'))
        if tier and cost is not None:
            crate_cost_by_tier[tier.lower()] = cost

    retained: List[Dict[str, Any]] = []

    # B. Filter campaigns
    for c in campaigns_raw:
        cid = s_norm(c.get('campaign_id'))
        if not cid:
            continue
        analysis_flag = s_norm(c.get('analysis_flag')).lower()
        if analysis_flag != 'review':
            continue
        if cid in held_campaign_ids:
            continue
        retained.append(c)

    # Prepare model assumptions
    models = {
        '6_day': {'days_per_dispatch': Decimal('6'), 'dispatches_per_year': Decimal('60')},
        '12_day': {'days_per_dispatch': Decimal('12'), 'dispatches_per_year': Decimal('30')},
    }

    out_campaigns: List[Dict[str, Any]] = []

    total_margin_6 = Decimal('0')
    total_margin_12 = Decimal('0')

    for c in retained:
        cid = s_norm(c.get('campaign_id'))
        cname = s_norm(c.get('campaign_name'))
        alias_labels = maybe_parse_alias_labels(c.get('alias_labels'))

        # C. Resolve billing
        billing_labels = [cname] + alias_labels
        payment, billing_row = latest_billing_payment(billing_rows, billing_labels)
        if payment is None:
            # Contract doesn't define behavior for missing billing; treat as 0 revenue.
            payment = Decimal('0')

        # D. Resolve active clinics
        active_clinics, override_row = resolve_active_clinics(
            overrides_rows,
            cid,
            c.get('default_active_clinics'),
        )

        # E. Look up crate cost
        crate_tier = s_norm(c.get('crate_tier'))
        crate_cost = crate_cost_by_tier.get(crate_tier.lower())
        if crate_cost is None:
            crate_cost = Decimal('0')

        drug_cost_per_1000 = dnum(c.get('drug_cost_per_1000_doses_usd')) or Decimal('0')
        doses_per_day = dnum(c.get('doses_per_day')) or Decimal('0')

        per_model: Dict[str, Dict[str, Any]] = {}
        margins: Dict[str, Decimal] = {}

        for key, m in models.items():
            days_per_dispatch = m['days_per_dispatch']
            dispatches_per_year = m['dispatches_per_year']

            annual_revenue = payment * active_clinics * dispatches_per_year
            annual_drug_cost = (
                drug_cost_per_1000
                * active_clinics
                * doses_per_day
                * days_per_dispatch
                * dispatches_per_year
                / Decimal('1000')
            )
            # Per instructions: annual_crate_cost = crate_cost_usd * dispatches_per_year
            annual_crate_cost = crate_cost * dispatches_per_year
            annual_margin = annual_revenue - annual_drug_cost - annual_crate_cost

            annual_revenue_r = round2(annual_revenue)
            annual_drug_cost_r = round2(annual_drug_cost)
            annual_crate_cost_r = round2(annual_crate_cost)
            annual_margin_r = round2(annual_margin)

            per_model[key] = {
                'days_per_dispatch': int(days_per_dispatch),
                'dispatches_per_year': int(dispatches_per_year),
                'annual_revenue_usd': float(annual_revenue_r),
                'annual_drug_cost_usd': float(annual_drug_cost_r),
                'annual_crate_cost_usd': float(annual_crate_cost_r),
                'annual_margin_usd': float(annual_margin_r),
            }
            margins[key] = annual_margin_r

        diff = round2(margins['12_day'] - margins['6_day'])

        total_margin_6 += margins['6_day']
        total_margin_12 += margins['12_day']

        out_campaigns.append(
            {
                'campaign_id': cid,
                'campaign_name': cname,
                'alias_labels': alias_labels,
                'resolved': {
                    'payment_per_dispatch_per_clinic_usd': float(round2(payment)),
                    'billing_cycle_tag': None if billing_row is None else s_norm(billing_row.get('cycle_tag')),
                    'billing_campaign_label': None if billing_row is None else s_norm(billing_row.get('campaign_label')),
                    'active_clinics': float(round2(active_clinics)),
                    'active_clinics_source': 'override' if override_row is not None else 'default',
                    'active_clinics_revision': None if override_row is None else s_norm(override_row.get('revision')),
                    'crate_tier': crate_tier,
                    'crate_cost_usd': float(round2(crate_cost)),
                    'drug_cost_per_1000_doses_usd': float(round2(drug_cost_per_1000)),
                    'doses_per_day': float(round2(doses_per_day)),
                },
                'models': {
                    'six_day': per_model['6_day'],
                    'twelve_day': per_model['12_day'],
                },
                'difference_12_minus_6_annual_margin_usd': float(diff),
            }
        )

    # I. Sort by campaign_id
    out_campaigns.sort(key=lambda cc: cc.get('campaign_id', ''))

    # G. Totals
    total_6 = round2(total_margin_6)
    total_12 = round2(total_margin_12)
    total_diff = round2(total_12 - total_6)
    abs_total_diff = round2(abs(total_diff))

    # H. Decision
    threshold = Decimal('11000')
    decision = 'move_to_12_day' if abs_total_diff < threshold else 'keep_6_day'
    justification = (
        f"Total annual margin (6-day)=${float(total_6):,.2f}; "
        f"(12-day)=${float(total_12):,.2f}; "
        f"difference (12-6)=${float(total_diff):,.2f}; "
        f"abs(difference)=${float(abs_total_diff):,.2f} vs threshold=${float(threshold):,.2f}."
    )

    analysis = {
        'assumptions': {
            'models': {
                'six_day': {'days_per_dispatch': 6, 'dispatches_per_year': 60},
                'twelve_day': {'days_per_dispatch': 12, 'dispatches_per_year': 30},
            },
            'margin_decision_threshold_abs_usd': float(threshold),
            'crate_cost_interpretation': 'crate_cost_usd is per dispatch; annual_crate_cost = crate_cost_usd * dispatches_per_year',
            'billing_resolution': 'campaign_label matches campaign_name or alias_labels; status=active; choose latest lexicographic cycle_tag',
            'active_clinics_resolution': 'use highest numeric revision among approved overrides with non-empty revision/active_clinics; else default_active_clinics',
            'rounding': 'All currency values rounded to 2 decimals (half up) after computation.',
        },
        'campaigns': out_campaigns,
        'totals': {
            'total_annual_margin_6_day_usd': float(total_6),
            'total_annual_margin_12_day_usd': float(total_12),
            'total_annual_margin_difference_12_minus_6_usd': float(total_diff),
            'absolute_total_margin_difference_usd': float(abs_total_diff),
        },
        'recommendation': {
            'decision': decision,
            'justification': justification,
        },
    }

    # J. Write JSON
    with open('/root/vaxcrate_analysis.json', 'w') as f:
        json.dump(analysis, f, indent=2)
        f.write('\n')

    # K. Write summary
    summary_lines = [
        f"Total 6-day annual margin (USD): {float(total_6):,.2f}",
        f"Total 12-day annual margin (USD): {float(total_12):,.2f}",
        f"Absolute difference (USD): {float(abs_total_diff):,.2f}",
        f"Decision: {decision}",
        f"Threshold (abs USD): {float(threshold):,.2f}",
    ]
    with open('/root/vaxcrate_summary.md', 'w') as f:
        f.write("\n".join(summary_lines) + "\n")


if __name__ == '__main__':
    main()

